INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-16-z0-q0','nism-16-z0','The spot price of a commodity is ₹6410 and the near-month futures price is ₹6425. The basis (spot − futures) is:','["₹15","-₹15","₹6,410","₹6,425"]',1,'Basis = spot − futures; a negative value indicates contango.',0) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-16-z0-q1','nism-16-z0','The convenience yield is:','["A margin refund","The interest on a bond","The benefit of holding the physical commodity rather than the futures","A tax rebate"]',2,'A high convenience yield can cause backwardation.',1) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-16-z0-q2','nism-16-z0','A trader buys 4 lot(s) of a commodity future (lot size 1 units) at ₹55300 and sells at ₹55680. The profit/(loss), ignoring costs, is:','["₹380","₹3,040","-₹1,520","₹1,520"]',3,'P/L = (exit − entry) × lot size × lots.',2) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
